			}
			catch (Exception e) when (e is AddressOutOfBoundsException or MemoryAccessException) {
				return 0;
			}
		}

		lock (this) {
			refreshIfNeeded();
			Array.Copy(bytes, offset, b, 0, b.length);
			return b.length;
		}
	}

